lazy_static! {
    pub static ref HAS_TRUECOLOR_SUPPORT: bool = if let Ok(truecolor) = env::var("COLORTERM") {
        truecolor == "truecolor" || truecolor == "24bit"
    } else {
        false
    };
}

impl Project {
    /// Gets the closest plain color to the TrueColor
    pub fn name_in_closest_terminal_color(&self, red: u8, green: u8, blue: u8) -> ColoredString {
        let colors = vec![
            (0, 0, 0),       //Black
            (205, 0, 0),     //Red
            (0, 205, 0),     //Green
            (205, 205, 0),   //Yellow
            (0, 0, 238),     //Blue
            (205, 0, 205),   //Magenta
            (0, 205, 205),   //Cyan
            (229, 229, 229), //White
            (127, 127, 127), //BrightBlack
            (255, 0, 0),     //BrightRed
            (0, 255, 0),     //BrightGreen
            (255, 255, 0),   //BrightYellow
            (92, 92, 255),   //BrightBlue
            (255, 0, 255),   //BrightMagenta
            (0, 255, 255),   //BrightCyan
            (255, 255, 255), //BrightWhite
        ]
        .into_iter()
        .enumerate();

        let index = colors
            .map(|(index, (r, g, b))| {
                let rd = cmp::max(r, red) - cmp::min(r, red);
                let gd = cmp::max(g, green) - cmp::min(g, green);
                let bd = cmp::max(b, blue) - cmp::min(b, blue);
                let rd: u32 = rd.into();
                let gd: u32 = gd.into();
                let bd: u32 = bd.into();
                let distance: u32 = rd.pow(2) + gd.pow(2) + bd.pow(2);
                (distance, index)
            })
            .min_by(|(d1, _), (d2, _)| d1.cmp(d2))
            .unwrap()
            .1;

        match index {
            0 => self.name.black(),
            1 => self.name.red(),
            2 => self.name.green(),
            3 => self.name.yellow(),
            4 => self.name.blue(),
            5 => self.name.magenta(),
            6 => self.name.cyan(),
            7 => self.name.white(),
            8 => self.name.bright_black(),
            9 => self.name.bright_red(),
            10 => self.name.bright_green(),
            11 => self.name.bright_yellow(),
            12 => self.name.bright_blue(),
            13 => self.name.bright_magenta(),
            14 => self.name.bright_cyan(),
            15 => self.name.bright_white(),
            _ => self.name.white().clear(),
        }
    }
}

impl std::fmt::Display for Project {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let colored_name = match Rgb::from_hex_str(self.color.as_str()) {
            Ok(color) => {
                let red = color.get_red().round() as u8;
                let green = color.get_green().round() as u8;
                let blue = color.get_blue().round() as u8;

                if HAS_TRUECOLOR_SUPPORT.to_owned() {
                    self.name.truecolor(red, green, blue).bold()
                } else {
                    self.name_in_closest_terminal_color(red, green, blue).bold()
                }
            }
            Err(_) => self.name.bold(),
        };
        if self.active {
            write!(f, "{colored_name}")
        } else {
            write!(f, "{colored_name} (archived)")
        }

    fn network_organization_to_organization(
        network_organization: NetworkOrganization,
    ) -> Organization {
        Organization {
            id: network_organization.id,
            name: network_organization.name,
            admin: network_organization.admin,
            workspace_id: network_organization.workspace_id,
            workspace_name: network_organization.workspace_name,
            pricing_plan_name: network_organization.pricing_plan_name,
            permissions: network_organization.permissions.unwrap_or_default(),
        }
    }

    fn map_tasks(
        network_tasks: Vec<NetworkTask>,
        projects: &HashMap<i64, Project>,
    ) -> HashMap<i64, Task> {
        network_tasks
            .into_iter()
            .filter_map(|task| {
                projects.get(&task.project_id).map(|project| {
                    (
                        task.id,
                        Task {
                            id: task.id,
                            name: task.name,
                            project: project.clone(),
                            workspace_id: task.workspace_id,
                            active: task.active.unwrap_or(true),
                        },
                    )
                })
            })
            .collect()
    }

    fn map_network_time_entry(
        network_entry: NetworkTimeEntry,
        projects: &HashMap<i64, Project>,
        tasks: &HashMap<i64, Task>,
    ) -> TimeEntry {
        TimeEntry {
            id: network_entry.id,
            description: network_entry.description,
            start: network_entry.start,
            stop: network_entry.stop,
            duration: network_entry.duration,
            billable: network_entry.billable,
            workspace_id: network_entry.workspace_id,
            tags: network_entry.tags.unwrap_or_default(),
            project: projects
                .get(&network_entry.project_id.unwrap_or(-1))
                .cloned(),
            task: tasks.get(&network_entry.task_id.unwrap_or(-1)).cloned(),
            ..Default::default()
        }
    }

    /// Hydrates a single NetworkTimeEntry by fetching projects/tasks/clients
    /// only when the entry references a project_id or task_id.
    async fn hydrate_single_network_entry(&self, network_entry: NetworkTimeEntry) -> TimeEntry {
        let has_project = network_entry.project_id.is_some();
        let has_task = network_entry.task_id.is_some();

        if !has_project && !has_task {
            return TimeEntry {
                id: network_entry.id,
                description: network_entry.description,
                start: network_entry.start,
                stop: network_entry.stop,
                duration: network_entry.duration,
                billable: network_entry.billable,
                workspace_id: network_entry.workspace_id,
                tags: network_entry.tags.unwrap_or_default(),
                project: None,
                task: None,
                ..Default::default()
            };
        }

        let (network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_projects(),
            async {
                if has_task {
                    self.get_tasks().await
                } else {
                    Ok(Vec::new())
                }
            },
            self.get_clients(),
        );

        let clients = Self::map_clients(network_clients.unwrap_or_default());
        let projects = Self::map_projects(network_projects.unwrap_or_default(), &clients);
        let tasks = Self::map_tasks(network_tasks.unwrap_or_default(), &projects);

        Self::map_network_time_entry(network_entry, &projects, &tasks)
    }

    async fn get_project_by_id(&self, project_id: i64) -> ResultWithDefaultError<Project> {
        let network_project = self
            .get_projects()
            .await?
            .into_iter()
            .find(|project| project.id == project_id)
            .ok_or_else(|| -> Box<dyn std::error::Error + Send> {
                Box::new(ApiError::Deserialization)
            })?;
        Ok(Self::network_project_to_project(network_project))
    }

