        // on Free plans) returns HTTP 403 "managed challenge" for requests with an
        // empty UA, which otherwise takes down any self-hosted OpenToggl instance
        // sitting behind Cloudflare (including our CI target track.opentoggl.com).
        let user_agent = concat!("toggl-cli/", env!("CARGO_PKG_VERSION"));
        let base_client = Client::builder()
            .default_headers(headers)
            .user_agent(user_agent);
        let http_client = {
            if let Some(proxy) = proxy {
                base_client.proxy(reqwest::Proxy::all(proxy).expect("Invalid proxy"))
            } else {
                base_client
            }
        }
        .build()
        .expect("Couldn't build a http client");
        let is_official_service = credentials.api_url.is_none();
        let base_url = credentials
            .api_url
            .unwrap_or_else(|| constants::TOGGL_API_URL_OFFICIAL.to_string());
        let api_client = Self {
            http_client,
            base_url,
            is_official_service,
            cache_namespace,
            last_time_entry_mutation: std::sync::Arc::new(std::sync::Mutex::new(None)),
            last_related_mutation: std::sync::Arc::new(std::sync::Mutex::new(
                std::collections::HashMap::new(),
            )),
        };
        Ok(api_client)
    }

